import { Octokit } from '@octokit/rest';
import { FixedFile, PRData } from './types';

function getOctokit(): Octokit {
  const token = process.env.GITHUB_TOKEN;
  if (!token) throw new Error('GITHUB_TOKEN env var is required');
  return new Octokit({ auth: token });
}

/**
 * Creates a new branch off the given SHA for housing auto-fixes.
 * Returns the created branch name.
 */
export async function createFixBranch(
  owner: string,
  repo: string,
  headSHA: string,
  prNumber: number,
): Promise<string> {
  const octokit = getOctokit();
  const branchName = `fix/auto-review-${prNumber}-${Date.now()}`;

  await octokit.rest.git.createRef({
    owner,
    repo,
    ref: `refs/heads/${branchName}`,
    sha: headSHA,
  });

  console.log(`[branch-manager] Created fix branch: ${branchName}`);
  return branchName;
}

/**
 * Commits each fixed file onto the specified branch.
 * Creates or updates files as needed.
 */
export async function commitFixes(
  owner: string,
  repo: string,
  branch: string,
  files: FixedFile[],
): Promise<void> {
  const octokit = getOctokit();

  for (const file of files) {
    let existingSha: string | undefined;

    try {
      const existing = await octokit.rest.repos.getContent({
        owner,
        repo,
        path: file.filename,
        ref: branch,
      });
      const data = existing.data;
      if (!Array.isArray(data) && 'sha' in data) {
        existingSha = data.sha;
      }
    } catch {
      // File doesn't exist on this branch yet — that's fine.
    }

    const encodedContent = Buffer.from(file.newContent, 'utf-8').toString('base64');

    await octokit.rest.repos.createOrUpdateFileContents({
      owner,
      repo,
      path: file.filename,
      message: `fix(auto-review): ${file.changesSummary}`,
      content: encodedContent,
      branch,
      ...(existingSha ? { sha: existingSha } : {}),
    });

    console.log(`[branch-manager] Committed fix to ${file.filename} on ${branch}`);
  }
}

/**
 * Opens a new "fix" PR targeting the original PR's head branch.
 * Returns the URL of the newly created PR.
 */
export async function openFixPR(
  owner: string,
  repo: string,
  originalPR: PRData,
  fixBranch: string,
): Promise<string> {
  const octokit = getOctokit();

  const { data } = await octokit.rest.pulls.create({
    owner,
    repo,
    title: `[Auto-fix] ${originalPR.prTitle}`,
    body: [
      `## Automated Fix for PR #${originalPR.prNumber}`,
      '',
      `This PR was automatically generated by the **PR Review Pipeline** to address`,
      `CRITICAL and HIGH severity issues found in #${originalPR.prNumber}.`,
      '',
      '### Original PR Details',
      `- **Number:** #${originalPR.prNumber}`,
      `- **Branch:** \`${originalPR.headBranch}\``,
      `- **Title:** ${originalPR.prTitle}`,
      '',
      '> ⚠️ Review all changes carefully before merging.',
      '',
      '---',
      '*🤖 Generated by PR Review Pipeline*',
    ].join('\n'),
    head: fixBranch,
    base: originalPR.headBranch,
    draft: false,
  });

  console.log(`[branch-manager] Opened fix PR: ${data.html_url}`);
  return data.html_url;
}
